(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[250,695,776],{8168:(e,o,t)=>{Promise.resolve().then(t.bind(t,8301))},8301:(e,o,t)=>{"use strict";t.d(o,{default:()=>r});var a=t(5155),s=t(2115);let i=JSON.parse('{"en":{"labels":{"updated":"Last updated: October 9, 2026","operator":"Operated by Joey Zhou / IdeaSpike. Contact:"},"privacy":{"title":"Privacy Policy","body":"<h2>What the app does</h2><p>Prices Nearby reads product price tags and compares nearby price observations. Uploaded photos stay owner-only. When you confirm a scan, its validated product, price, conditions, observation time and public store location may be shared in other users’ comparisons. Your original photo and precise capture coordinates are not shown in those comparisons.</p><h2>Information we process</h2><p>We process your email and account identifier for sign-in, the photo you choose or take, capture time and time zone, photo GPS when present, and the phone location available when you capture or select the photo. Recognition, store matches, corrections and feedback are linked to the scan. Service identifiers, errors, processing times and model usage help operate and diagnose the app.</p><h2>Providers and location</h2><p>AWS supplies authentication, protected photo storage, service infrastructure and store search. OpenAI processes a resized, metadata-free copy of the photo for recognition; the app does not send raw GPS coordinates to the vision model. We request that OpenAI not store the analysis response. Provider processing and retention follow their own policies, including <a href=\\"https://developers.openai.com/api/docs/guides/your-data\\">OpenAI API data controls</a>. Processing may occur outside your country, including the United States. Location access is optional and used while the app is in use. The system photo picker accesses the selected photo rather than requesting the entire library.</p><h2>Retention and local cache</h2><p>Cloud photos are scheduled to expire after 90 days and scan/price metadata after 365 days. Lifecycle cleanup is asynchronous and may take additional time. Service logs are configured for approximately 30 days. Account information remains until removed. A protected, account-separated device cache has a 64 MiB limit, including metadata, with no time-based expiry. When full, it removes the least recently used photos. Local copies may outlive cloud-photo retention until capacity eviction, sign-out, uninstall or operating-system cache reclamation. Cache files and local scan history are excluded from device backups. Signing out or changing accounts clears the previous account’s photo cache; local history references remain account-separated. The app never saves signed download URLs, tokens in that cache, or photos into your Photos library.</p><h2>Your choices and assistance</h2><p>You may deny location access, select only photos you wish to upload, mark incorrect information and sign out. Taking or choosing a photo starts upload and recognition. Use only photos you have permission to share and avoid including people or unnecessary personal information. Contact support@ideaspike.com for access, correction, or account/cloud-data deletion assistance. This release does not provide an in-app account deletion control. Removing the app removes its local files but does not itself remove cloud records. Applicable privacy rights remain available.</p><h2>Other services and updates</h2><p>The app includes no advertising or cross-app tracking SDK. Apple’s App Store, TestFlight and device services have their own policies. Feedback you choose to send through TestFlight may be reviewed by the developer. Opening website links sends normal web request information to the destination; information you send to support is used to respond. We update this product-specific policy when processing changes.</p>"},"terms":{"title":"Terms of Use","body":"<h2>Price observations</h2><p>Prices Nearby helps compare observed product prices. Recognition, store matching and unit conversions may be incomplete or incorrect. Observations can become outdated; stock, taxes, membership, promotion dates, purchase limits and package differences can affect the checkout price. Check the label and store before purchasing. A comparison is not a reservation, a retailer offer, or a guarantee of savings.</p><h2>Your account and submissions</h2><p>Keep account access secure. Upload only photos you have rights and permission to share. Do not fabricate price labels, misrepresent stores, submit unlawful content or abuse the service. Your photos remain yours; you allow us and our service providers to store and process them to provide recognition, comparisons and problem investigation. Confirming a scan can share its validated price observation and public store location, as described in the Privacy Policy. Source photos are not publicly posted.</p><h2>Review and availability</h2><p>A scan with no detected price tag ends without manual product/price submission. Review marks and corrections help identify mistakes; they do not guarantee the accuracy of the result. Features depend on supported iOS versions, connectivity and service providers. We may update, limit, suspend or discontinue features and do not guarantee uninterrupted availability.</p><h2>Current release and contact</h2><p>This release does not implement payments or subscriptions. No paid entitlement or purchase is required by these terms. Any future payment offering needs its own disclosed terms. Nothing here excludes rights or responsibilities that cannot be excluded under applicable law. Contact support@ideaspike.com for questions or service assistance. Updates appear on this page.</p>"},"support":{"title":"Prices Nearby Support","body":"<h2>Good Price Nearby</h2><p>Photograph a complete product price tag to compare nearby observations. Keep the label readable in the dashed guide; recognition uses the whole photo. A photo without a detected price tag ends the scan.</p><h2>History and store matches</h2><p>Scan History reopens saved details and uses a bounded local photo cache to avoid repeat downloads. Photo GPS takes priority over the phone’s current position. Visible store names and branch addresses guide matching. Without photo GPS, the app falls back to phone location and automatically uses the best available supported-store match, including when stores are close together. No store confirmation is required; location warnings are informational. A store match is not proof of the branch.</p><h2>Get help</h2><p>Email <a href=\\"mailto:support@ideaspike.com\\">support@ideaspike.com</a> with the app version and a short description. Include a scan ID only if you want us to investigate that scan. Do not email passwords or sign-in codes. You can also use TestFlight feedback during internal testing.</p>"}},"zh-Hans":{"labels":{"updated":"更新于 2026 年 10 月 9 日","operator":"运营者：Joey Zhou / IdeaSpike。联系："},"privacy":{"title":"隐私政策","body":"<h2>应用提供什么</h2><p>附近价格读取商品价签并比较附近的价格记录。上传照片仅供所属账户查看。你确认扫描后，通过验证的商品、价格、条件、观察时间及公开门店位置可能出现在其他用户的比价结果中。原始照片和精确拍摄坐标不会在这些结果中显示。</p><h2>处理的信息</h2><p>我们处理用于登录的邮箱和账户标识、你选择或拍摄的照片、扫描时间与时区、照片自带的 GPS，以及拍摄或选图时可用的手机位置。识别结果、门店匹配、修正及反馈与扫描记录关联。服务标识、错误、处理耗时和模型用量用于运行及排查问题。</p><h2>服务商与定位</h2><p>AWS 提供身份认证、受保护照片存储、服务基础设施及门店搜索。OpenAI 使用缩小且去除元数据的照片副本进行识别；应用不会把原始 GPS 坐标发给视觉模型。我们请求 OpenAI 不保存分析响应。服务商的处理及保存遵循其政策，包括 <a href=\\"https://developers.openai.com/api/docs/guides/your-data\\">OpenAI API 数据控制</a>。处理可能发生在你所在国家以外，包括美国。定位可选，仅在使用应用时使用。系统选图器只访问所选照片，不请求整个相册。</p><h2>保存期限与本地缓存</h2><p>云端照片计划在 90 天后过期，扫描及价格元数据在 365 天后过期。生命周期清理是异步的，可能需要额外时间。服务日志配置为约 30 天。账户信息保留至被删除。设备上受保护、按账户隔离的照片缓存总量上限为 64 MiB（含元数据），不按天数过期。容量用满时会清理最久未使用的照片。本地副本可在云端照片到期后继续保留，直到容量清理、退出登录、卸载或系统回收缓存。缓存和本地扫描记录不进入设备备份。退出登录或切换账户会清除原账户照片缓存；本地历史引用仍按账户隔离。缓存不保存临时签名下载链接或令牌，应用不会把照片存入系统 Photos 相册。</p><h2>你的选择与协助</h2><p>你可拒绝定位、只选择愿意上传的照片、标记错误信息并退出登录。拍照或选图会开始上传和识别。请只使用有权分享的照片，避免包含人物或不必要的个人信息。如需访问、更正或账户与云端数据删除协助，请联系 support@ideaspike.com。本版没有应用内删除账户入口。删除应用会清除本地文件，但不会直接删除云端记录。适用的隐私权利仍然有效。</p><h2>其他服务与更新</h2><p>应用不包含广告或跨应用跟踪 SDK。Apple 的 App Store、TestFlight 及设备服务适用其自身政策。开发者可查看你主动通过 TestFlight 提交的反馈。打开网站链接会把常规网页请求信息发送到目标网站；你发给支持邮箱的信息用于回复。处理方式改变时会更新本应用专属政策。</p>"},"terms":{"title":"使用条款","body":"<h2>价格记录</h2><p>附近价格帮助比较观察到的商品价格。识别、门店匹配及单位换算可能不完整或错误。记录可能过时；库存、税费、会员条件、促销日期、购买限制及包装差异都可能影响结账价格。购买前请核对价签和门店。比价结果不代表预订、商家报价或节省金额保证。</p><h2>账户与上传</h2><p>请保护账户访问安全，只上传有权且获准分享的照片。不得伪造价签、冒充门店、上传违法内容或滥用服务。照片仍归你所有；你允许我们及服务商为识别、比价和问题调查存储及处理照片。确认扫描可分享通过验证的价格记录和公开门店位置，具体见隐私政策。原始照片不会公开发布。</p><h2>检查与可用性</h2><p>未检测到价签的扫描会结束，不提供手工商品或价格提交。检查标记和修正用于发现错误，不保证结果准确。功能依赖受支持的 iOS、网络及服务商。我们可能更新、限制、暂停或停止功能，不保证持续可用。</p><h2>当前版本与联系</h2><p>本版没有实现付费或订阅，这些条款不要求购买或付费权益。未来付费方案需另行公布条款。本页不排除适用法律规定不得排除的权利或责任。问题或服务协助请联系 support@ideaspike.com。更新会在本页发布。</p>"},"support":{"title":"附近价格支持","body":"<h2>Good Price Nearby</h2><p>拍摄完整商品价签来比较附近价格。让价签在虚线框附近清晰可读；识别仍覆盖整张照片。未检测到价签时会结束扫描。</p><h2>历史与门店匹配</h2><p>拍照记录可重新打开保存的详情，并使用有上限的本地照片缓存减少重复下载。照片 GPS 优先于当前手机位置。可见店名和门店地址参与匹配。没有照片 GPS 时，应用会使用手机位置，自动采用现有证据下的最佳支持门店匹配，相邻门店也不要求确认。定位提示仅供参考，匹配结果不代表门店证明。</p><h2>获取帮助</h2><p>请把应用版本及简短问题描述发至 <a href=\\"mailto:support@ideaspike.com\\">support@ideaspike.com</a>。仅在希望调查某次扫描时提供扫描 ID。不要发送密码或登录验证码。内部测试期间也可通过 TestFlight 反馈。</p>"}},"zh-Hant":{"labels":{"updated":"更新於 2026 年 10 月 9 日","operator":"營運者：Joey Zhou / IdeaSpike。聯絡："},"privacy":{"title":"隱私政策","body":"<h2>App 提供什麼</h2><p>附近價格讀取商品價牌並比較附近的價格記錄。上傳照片僅供所屬帳號查看。你確認掃描後，通過驗證的商品、價格、條件、觀察時間及公開門市位置可能出現在其他使用者的比價結果中。原始照片和精確拍攝座標不會在這些結果中顯示。</p><h2>處理的資訊</h2><p>我們處理用於登入的電子郵件和帳號識別、你選擇或拍攝的照片、掃描時間與時區、照片附帶的 GPS，以及拍攝或選圖時可用的手機位置。辨識結果、門市配對、修正及回饋與掃描記錄關聯。服務識別、錯誤、處理時間和模型用量用於執行及排查問題。</p><h2>服務商與定位</h2><p>AWS 提供身分驗證、受保護照片儲存、服務基礎設施及門市搜尋。OpenAI 使用縮小且移除中繼資料的照片副本進行辨識；App 不會將原始 GPS 座標傳給視覺模型。我們請求 OpenAI 不儲存分析回應。服務商的處理及保存遵循其政策，包括 <a href=\\"https://developers.openai.com/api/docs/guides/your-data\\">OpenAI API 資料控制</a>。處理可能發生在你所在國家以外，包括美國。定位可選，僅在使用 App 時使用。系統選圖器只存取所選照片，不請求整個相簿。</p><h2>保存期限與本機快取</h2><p>雲端照片計畫在 90 天後到期，掃描及價格中繼資料在 365 天後到期。生命週期清理是非同步的，可能需要額外時間。服務日誌設定為約 30 天。帳號資訊保留至被刪除。裝置上受保護、按帳號隔離的照片快取總量上限為 64 MiB（含中繼資料），不按天數過期。容量用滿時會清理最久未使用的照片。本機副本可在雲端照片到期後繼續保留，直到容量清理、登出、移除 App 或系統回收快取。快取和本機掃描記錄不進入裝置備份。登出或切換帳號會清除原帳號照片快取；本機歷史引用仍按帳號隔離。快取不儲存暫時簽名下載連結或權杖，App 不會將照片存入系統 Photos 相簿。</p><h2>你的選擇與協助</h2><p>你可拒絕定位、只選擇願意上傳的照片、標記錯誤資訊並登出。拍照或選圖會開始上傳和辨識。請只使用有權分享的照片，避免包含人物或不必要的個人資訊。如需存取、更正或帳號與雲端資料刪除協助，請聯絡 support@ideaspike.com。本版沒有 App 內刪除帳號入口。刪除 App 會清除本機檔案，但不會直接刪除雲端記錄。適用的隱私權利仍然有效。</p><h2>其他服務與更新</h2><p>App 不包含廣告或跨 App 追蹤 SDK。Apple 的 App Store、TestFlight 及裝置服務適用其自身政策。開發者可查看你主動透過 TestFlight 提交的回饋。開啟網站連結會將一般網頁請求資訊傳送至目標網站；你傳給支援信箱的資訊用於回覆。處理方式改變時會更新本 App 專屬政策。</p>"},"terms":{"title":"使用條款","body":"<h2>價格記錄</h2><p>附近價格協助比較觀察到的商品價格。辨識、門市配對及單位換算可能不完整或錯誤。記錄可能過時；庫存、稅費、會員條件、促銷日期、購買限制及包裝差異都可能影響結帳價格。購買前請核對價牌和門市。比價結果不代表預訂、商家報價或節省金額保證。</p><h2>帳號與上傳</h2><p>請保護帳號存取安全，只上傳有權且獲准分享的照片。不得偽造價牌、冒充門市、上傳違法內容或濫用服務。照片仍歸你所有；你允許我們及服務商為辨識、比價和問題調查儲存及處理照片。確認掃描可分享通過驗證的價格記錄和公開門市位置，詳見隱私政策。原始照片不會公開發佈。</p><h2>檢查與可用性</h2><p>未偵測到價牌的掃描會結束，不提供手工商品或價格提交。檢查標記和修正用於發現錯誤，不保證結果準確。功能依賴受支援的 iOS、網路及服務商。我們可能更新、限制、暫停或停止功能，不保證持續可用。</p><h2>目前版本與聯絡</h2><p>本版沒有實作付費或訂閱，這些條款不要求購買或付費權益。未來付費方案需另行公布條款。本頁不排除適用法律規定不得排除的權利或責任。問題或服務協助請聯絡 support@ideaspike.com。更新會在本頁發佈。</p>"},"support":{"title":"附近價格支援","body":"<h2>Good Price Nearby</h2><p>拍攝完整商品價牌來比較附近價格。讓價牌在虛線框附近清晰可讀；辨識仍涵蓋整張照片。未偵測到價牌時會結束掃描。</p><h2>歷史與門市配對</h2><p>拍照記錄可重新開啟保存的詳情，並使用有上限的本機照片快取減少重複下載。照片 GPS 優先於目前手機位置。可見店名和門市地址參與配對。沒有照片 GPS 時，App 會使用手機位置，自動採用現有證據下的最佳支援門市配對，相鄰門市也不要求確認。定位提示僅供參考，配對結果不代表門市證明。</p><h2>取得協助</h2><p>請將 App 版本及簡短問題描述傳至 <a href=\\"mailto:support@ideaspike.com\\">support@ideaspike.com</a>。僅在希望調查某次掃描時提供掃描 ID。不要傳送密碼或登入驗證碼。內部測試期間也可透過 TestFlight 回饋。</p>"}}}');function r(e){let{kind:o}=e,[t,r]=(0,s.useState)("en");(0,s.useEffect)(()=>{let e=new URLSearchParams(window.location.search).get("lang");"en"===e||"zh-Hans"===e||"zh-Hant"===e?r(e):navigator.language.toLowerCase().startsWith("zh")&&r(/hant|tw|hk|mo/i.test(navigator.language)?"zh-Hant":"zh-Hans")},[]);let n=i[t][o],p=i[t].labels;return(0,a.jsx)("main",{lang:t,className:"min-h-screen bg-[#f8faf9] px-5 py-10 text-[#182934]",children:(0,a.jsxs)("article",{className:"mx-auto max-w-3xl rounded-2xl bg-white p-6 shadow-sm sm:p-10",children:[(0,a.jsxs)("div",{className:"mb-7 flex flex-wrap items-center justify-between gap-4",children:[(0,a.jsx)("a",{href:"https://ideaspike.com",className:"font-semibold text-[#0163ac]",children:"Prices Nearby"}),(0,a.jsxs)("label",{className:"text-sm",children:[(0,a.jsx)("span",{className:"sr-only",children:"Language / 语言 / 語言"}),(0,a.jsxs)("select",{value:t,onChange:e=>r(e.target.value),className:"rounded-lg border border-gray-200 bg-white px-3 py-2",children:[(0,a.jsx)("option",{value:"en",children:"English"}),(0,a.jsx)("option",{value:"zh-Hans",children:"简体中文"}),(0,a.jsx)("option",{value:"zh-Hant",children:"繁體中文"})]})]})]}),(0,a.jsx)("h1",{className:"mb-3 text-3xl font-bold",children:n.title}),(0,a.jsx)("p",{className:"mb-8 text-sm text-gray-500",children:p.updated}),(0,a.jsx)("div",{className:"leading-7 [&_h2]:mb-3 [&_h2]:mt-8 [&_h2]:text-xl [&_h2]:font-semibold [&_p]:mb-4 [&_a]:text-[#0163ac] [&_a]:underline",dangerouslySetInnerHTML:{__html:n.body}}),(0,a.jsxs)("nav",{"aria-label":"Prices Nearby information",className:"mt-7 flex flex-wrap gap-5 text-sm text-[#0163ac] underline",children:[(0,a.jsx)("a",{href:"/prices-nearby/support/?lang=".concat(t),children:i[t].support.title}),(0,a.jsx)("a",{href:"/prices-nearby/privacy/?lang=".concat(t),children:i[t].privacy.title}),(0,a.jsx)("a",{href:"/prices-nearby/tos/?lang=".concat(t),children:i[t].terms.title})]}),(0,a.jsxs)("footer",{className:"mt-10 border-t border-gray-100 pt-5 text-sm text-gray-500",children:[p.operator," ",(0,a.jsx)("a",{className:"text-[#0163ac]",href:"mailto:support@ideaspike.com",children:"support@ideaspike.com"})]})]})})}}},e=>{var o=o=>e(e.s=o);e.O(0,[441,684,358],()=>o(8168)),_N_E=e.O()}]);